test_suite:
test('union contains all elements', () => {
  const result = union(new Set([1, 2]), new Set([2, 3]));
  expect(result).toEqual(new Set([1, 2, 3]));
});

test('intersection contains common elements', () => {
  const result = intersection(new Set([1, 2, 3]), new Set([2, 3, 4]));
  expect(result).toEqual(new Set([2, 3]));
});

test('difference contains elements in a not in b', () => {
  const result = difference(new Set([1, 2, 3]), new Set([2, 3]));
  expect(result).toEqual(new Set([1]));
});

test('intersection of disjoint sets is empty', () => {
  const result = intersection(new Set([1, 2]), new Set([3, 4]));
  expect(result.size).toBe(0);
});

// __hidden__
test('difference returns empty set when a is subset of b', () => {
  const result = difference(new Set([1, 2]), new Set([1, 2, 3]));
  expect(result.size).toBe(0);
});

solution:
export function union(a, b) {
  return new Set([...a, ...b]);
}

export function intersection(a, b) {
  return new Set([...a].filter(x => b.has(x)));
}

export function difference(a, b) {
  return new Set([...a].filter(x => !b.has(x)));
}
